import numpy as np

def summary_stats_by_block(x, n_blocks):
    blocks = np.array_split(np.asarray(x, dtype=float), n_blocks)
    return np.array([[b.mean(), b.std(ddof=1)] for b in blocks])

import numpy as np

def log_returns(prices):
    p = np.asarray(prices, dtype=float)
    return np.log(p[1:] / p[:-1])
